/// The on-chain account ID for the Treasury pallet.
/// Used in chain_spec genesis config to pre-fund the Treasury.
/// Derivation: PalletId(*b"sc/trsry").into_account_truncating()
pub fn treasury_account_id() -> AccountId {
    use frame_support::PalletId;
    use sp_runtime::traits::AccountIdConversion;
    PalletId(*b"sc/trsry").into_account_truncating()
}

