// ─── Version ─────────────────────────────────────────────────────────────────
#[sp_version::runtime_version]
pub const VERSION: RuntimeVersion = RuntimeVersion {
    // `create_runtime_str!` is deprecated in favour of `Cow::Borrowed`. Same
    // value, same encoding — the macro expanded to exactly this.
    spec_name: ::sp_std::borrow::Cow::Borrowed("scalar-commons"),
    impl_name: ::sp_std::borrow::Cow::Borrowed("scalar-commons"),
    authoring_version: 1,
    // 300 -> 301: added pallet-referenda Instance2 (RankedPolls) at index 41.
    // Adding a pallet changes the storage layout, which CLAUDE.md requires be
    // accompanied by a spec_version bump. No migration is needed: this runtime
    // has never produced a WASM blob, so there is no live chain state to move.
    //
    // 301 -> 302: declared AuthorityDiscoveryApi. This adds an entry to
    // RUNTIME_API_VERSIONS below, which is part of the RuntimeVersion a node
    // checks before it will execute a block, so it must be accompanied by a
    // bump even though no storage layout changed. No migration: the API is
    // read-only over pallet_authority_discovery's existing Keys/NextKeys
    // storage, which is already populated by pallet-session every rotation.
    //
    // 302 -> 303: pallet-orchestrator "link kit" (ROUND9). Adds the
    // PendingProposalCount storage map, two extrinsics (decline_link_proposal
    // at call index 6, cancel_link_proposal at 7), two Error variants, two new
    // events plus a field on OrchestratorDeregistered; makes
    // propose_sub_agent_link permissive while capping a sub-agent's proposal
    // inbox at MaxPendingProposals. Storage layout and the call enum both
    // change, so CLAUDE.md requires the bump. No migration is written and none
    // is needed: this runtime has never launched on any network, so there is no
    // live state to move. The bump lands in the first commit of the series so
    // that no intermediate commit carries a layout change without one.
    //
    // 303 -> 304: ROUND14 governance-credit and diversity-ordering fixes. Adds the
    // EraGovVotedPolls storage double map to pallet-agents, changes the
    // agents::record_gov_vote call signature (now takes a poll_index) and the
    // GovVoteRecorded event shape, and adds the PollAlreadyCredited error. Storage
    // layout and the call enum both change, so CLAUDE.md requires the bump.
    //
    // No data migration is written and none is needed, on two independent grounds.
    // First and sufficient: this runtime has never launched on any network, so there is
    // no live state to move. Second, and the reason this fix was chosen over the
    // alternatives: every map it touches is EPHEMERAL — EraGovVotedPolls is new and
    // starts empty, and both it and EraGovParticipation are cleared wholesale by
    // drain_era_maps every era, so even on a live chain there would be no per-agent data
    // to translate; at worst one era's governance counters reset. The alpha change
    // (4,000 -> 1,500 bps) needs no migration either: it is an auto-param, seeded at
    // genesis and mutable through governance thereafter.
    //
    // 304 -> 305: `type EraPayout` on pallet_staking::Config moves from
    // ConvertCurve<RewardCurve> to (), ending staking inflation. This is the
    // first upgrade applied to a LIVE chain rather than compiled into a fresh
    // genesis, so the bump is what makes the node accept the new code at all.
    //
    // No storage layout change and no migration. EraPayout is a Config type
    // consulted by pallet-staking's era rotation, not a storage item; nothing
    // in state is added, removed or re-shaped. Existing ErasValidatorReward
    // entries are untouched and stay claimable — see the note at the EraPayout
    // definition. The only behavioural difference is that the next era
    // rotation books a payout of zero.
    //
    // 305 -> 306: the economic gate. Issue #164 measured a two-account, faucet-funded
    // tester capturing 81.88 % of an era's emission — 90 068.37 CMN — for 60 CMN of escrow
    // it paid itself, because the pot is sized by `TargetEmissionPerAgent x agent_count`
    // and never looks at whether work happened. Issue #161: `register` never wrote
    // `LastHeartbeat`, so every agent registered on a live chain failed the `hb >= 90`
    // activity gate for a liveness failure it had no chance to avoid.
    //
    // Three changes, all with storage layout consequences, so the bump is mandatory and
    // BOTH pallets carry real migrations:
    //
    //   * pallet-emissions bounds the era emission at `alpha x qualifying escrow volume`
    //     (D7). No new storage of its own — it reads the two new agents maps — but one new
    //     event, EmissionCappedByVolume, appended last.
    //   * pallet-agents v1 -> v2: adds EraPairVolume (era-scoped, who paid whom) and
    //     LineageParent (declared funding groups), and its migration backfills
    //     LastHeartbeat for every agent that registered before D8 so the #161 population
    //     is not left permanently below the activity gate.
    //   * pallet-auto-params v1 -> v2: adds EmissionVolumeAlphaBps and its bounds. The
    //     migration is load-bearing rather than cosmetic — the value is ValueQuery, so
    //     without seeding it the upgraded chain would read alpha = 0 and bound every
    //     era's emission at zero forever.
    //
    // transaction_version is NOT bumped: agents::link_funding_lineage is appended at call
    // index 11 and ParamId::EmissionVolumeAlphaBps at discriminant 5, so no existing call
    // encoding moves.
    //
    // 307 -> 308: agent messaging, Round A (D14–D17). On-chain coordination messages plus a
    // per-agent messaging key, so negotiation that used to travel as JSON between chats is on
    // the same ledger as the escrow it leads to.
    //
    //   * pallet-agents: new `MessagingKey` map (optional X25519 public key per agent), two
    //     extrinsics appended at call indices 13 (`set_messaging_key`) and 14
    //     (`clear_messaging_key`), two events and one error appended last.
    //   * pallet-messages (new, pallet index 42 — the next unused index; nothing is renumbered):
    //     one extrinsic, `send`, whose payload is carried in the block and the event but never
    //     stored. Its only state is the per-sender `NextNonce` and the `SentInBlock` rate-limit
    //     counter.
    //
    // Storage layout changes, so the bump is mandatory. No migration, and no
    // STORAGE_VERSION change on pallet-agents: every change is ADDITIVE — two brand-new maps
    // in a brand-new pallet and one brand-new map in agents, all empty at the upgrade and
    // all OptionQuery/ValueQuery-with-zero-default, so nothing existing is read differently.
    // No genesis config is added, so the chain spec is untouched.
    //
    // transaction_version is NOT bumped: the new agents calls are appended after index 12 and
    // the new pallet sits at a previously unused index, so no existing call encoding moves.
    spec_version: 309,
    impl_version: 0,
    apis: RUNTIME_API_VERSIONS,
    transaction_version: 1,
    system_version: 1,
};

