/// EnsureOrigin returning the max Balance as Success (for SpendOrigin).
pub struct EnsureRootWithMaxBalance;
impl frame_support::traits::EnsureOrigin<RuntimeOrigin> for EnsureRootWithMaxBalance {
    type Success = Balance;
    fn try_origin(o: RuntimeOrigin) -> Result<Balance, RuntimeOrigin> {
        EnsureRoot::<AccountId>::try_origin(o).map(|_| Balance::MAX)
    }
    #[cfg(feature = "runtime-benchmarks")]
    fn try_successful_origin() -> Result<RuntimeOrigin, ()> {
        Ok(RuntimeOrigin::root())
    }
}

/// Identity balance converter (native-only treasury, AssetKind = ()).
pub struct NativeBalanceConverter;
impl frame_support::traits::tokens::ConversionFromAssetBalance<Balance, (), Balance>
    for NativeBalanceConverter
{
    type Error = sp_runtime::DispatchError;
    fn from_asset_balance(balance: Balance, _: ()) -> Result<Balance, Self::Error> {
        Ok(balance)
    }
    // ROUND6: the trait takes the asset id BY VALUE —
    // `fn ensure_successful(asset_id: AssetId);` in frame_support
    // (traits/tokens/misc.rs:312), and the SDK's own blanket impl at line 328
    // reads `fn ensure_successful(_: AssetId) {}`. This took `&()` and so never
    // satisfied the trait. It went unnoticed because it is cfg-gated behind
    // runtime-benchmarks, which had never successfully been enabled until
    // Round 5 completed the feature graph. E0053, and the only thing standing
    // between that graph and a green benchmarks build.
    #[cfg(feature = "runtime-benchmarks")]
    fn ensure_successful(_: ()) {}
}

